const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sources={ice:['NASA · Opwarming en terugkoppelingen','https://science.nasa.gov/earth/climate-change/global-warming/'],roots:['NOAA · Wat doet een mangrovebos?','https://oceanservice.noaa.gov/facts/mangroves.html'],shore:['NOAA · Natuurlijke kustbescherming','https://www.fisheries.noaa.gov/news/coastal-resiliency'],community:['NOAA · Kustnatuur en koolstof','https://www.fisheries.noaa.gov/national/habitat-conservation/protecting-coastal-blue-carbon-through-habitat-conservation']};
const stops={
 ice:{title:'Waarom maakt de ondergrond verschil?',intro:'Kijk naar het witte ijs en het donkere gesteente ernaast. Bij dezelfde zonnestraling kaatst een lichte sneeuwlaag meer energie terug dan een donkere ondergrond.',question:'Wat kan er gebeuren als witte sneeuw verdwijnt en donker terrein bloot komt te liggen?',options:[['absorb','De donkere ondergrond neemt meer zonenergie op; dat kan verdere opwarming versterken.'],['source','De donkere steen maakt zelf extra zonlicht.'],['stop','Alle opwarming stopt, want het ijs is weg.']],correct:'absorb',feedback:'Precies. Opwarming → minder sneeuw en ijs → minder teruggekaatst zonlicht → meer opgenomen energie → verdere opwarming. Dit is een versterkende terugkoppeling. De sterkte hangt van plaats en omstandigheden af.',ids:['climate-feedback'],source:'ice',extra:'Albedo is de naam voor het deel van het zonlicht dat een oppervlak terugkaatst. Je hoeft het woord niet uit je hoofd te leren om het proces te begrijpen. Het landschap is fictief; deze afbeelding meet geen ijsverlies.'},
 melt:{title:'Waar gaat het smeltwater heen?',intro:'De gletsjer rust op land. Hij krijgt ijs erbij door sneeuw en verliest ijs door smelten en andere processen. Als het verlies over langere tijd groter is dan de aanvoer, neemt de ijsmassa af.',question:'Waarom is de plek van het ijs belangrijk voor de zeespiegel?',options:[['land','Smeltend landijs kan water aan de oceaan toevoegen; drijvend zee-ijs werkt anders.'],['all','Elke ijssoort verhoogt de zeespiegel evenveel als hij smelt.'],['nothing','Landijs heeft nooit gevolgen buiten het dal.']],correct:'land',feedback:'Ja. Dit ijs ligt op land. Water dat uiteindelijk de oceaan bereikt kan de zeespiegel verhogen. Daarnaast zet warmer oceaanwater uit. Die processen verschillen van het rechtstreeks smelten van drijvend zee-ijs.',ids:['climate-impact-chain'],source:'ice',extra:'Je volgt een gevolgketen: opwarming → verlies van landijs → water richting oceaan → gevolgen voor kusten. Niet elk dal of iedere gletsjer reageert even snel.'},
 record:{title:'Een landschap vertelt nog niet alles',intro:'Je ziet ijs, rotsen en water. Het beeld maakt processen voorstelbaar, maar één bezoek bewijst nog niet hoeveel de gletsjer is veranderd of wat alle oorzaken zijn.',question:'Wat heb je nodig om een verandering goed te onderzoeken?',options:[['series','Vergelijkbare metingen over langere tijd, en gegevens over bijvoorbeeld sneeuw en temperatuur.'],['photo','Alleen deze mooie foto.'],['day','Alleen de temperatuur van vandaag.']],correct:'series',feedback:'Dat is de stap van indruk naar onderbouwd inzicht. Onderzoek ijsmassa of positie over tijd, gebruik vergelijkbare metingen en neem andere verklaringen mee. Je klimaatbasis uit het archief helpt hier.',ids:['weather-climate','indicators'],source:'ice',extra:'De speelplek is een verbeeld landschapstype. Er staan geen verzonnen historische meetwaarden bij die als echte gletsjerdata worden gepresenteerd.'},
 roots:{title:'Wat doen deze wortels voor de kust?',intro:'Mangroven zijn bomen en struiken in de kustzone waar eb en vloed elkaar afwisselen. Kijk naar het netwerk van wortels: het houdt bodem vast en biedt schuilplaatsen voor waterleven.',question:'Welke verbinding tussen natuur en mens zie je hier?',options:[['service','Leefgebied voor vissen en het vasthouden van bodem kunnen ook de kust en visserij ondersteunen.'],['decor','De wortels hebben alleen waarde omdat ze er mooi uitzien.'],['guarantee','Mangroven houden iedere overstroming tegen.']],correct:'service',feedback:'Juist. Dit zijn ecosysteemdiensten: functies van de natuur waar mensen ook van profiteren. Bescherming verschilt per locatie, bos en storm; mangroven maken een kust niet onkwetsbaar.',ids:['biodiversity-services'],source:'roots',extra:'Het gaat niet om “groen is altijd goed”, maar om een aantoonbare functie. Ook voldoende ruimte, waterkwaliteit en gezond waterverkeer bepalen of deze natuur kan blijven werken.'},
 shore:{title:'Kustherstel heeft meer dan één gevolg',intro:'Je ziet bestaande mangroven, een herstelstrook en een verharde kust. Mangroven kunnen koolstof opslaan en golven afremmen. Het behoud en herstel vraagt ruimte, beheer en afspraken.',question:'Hoe passen klimaatmaatregelen hier samen?',options:[['both','Koolstof behouden raakt de oorzaak van opwarming; bescherming van de kust helpt omgaan met gevolgen.'],['adapt','Kustbescherming zorgt op zichzelf dat wereldwijd geen CO₂ meer wordt uitgestoten.'],['carbon','Bomen opslaan betekent dat alle andere uitstoot onbeperkt mag doorgaan.']],correct:'both',feedback:'Ja. Minder uitstoot of meer behoud van koolstof hoort bij mitigatie. Je aanpassen aan gevolgen heet adaptatie. Eén project kan beide bijdragen, maar de omvang en houdbaarheid moeten worden gecontroleerd.',ids:['mitigation-adaptation','regenerative-design'],source:'shore',extra:'Biodiversiteit, visserij en koolstof kunnen samen profiteren; ze zijn geen verwisselbare punten op één score. Een herstelplan moet ook passen bij bodem, getij, soorten en gebruik.'},
 community:{title:'Wie kan van deze plek blijven leven?',intro:'Een kust is ook een plek om te wonen, vissen en werken. Bij een herstelproject kunnen sommige mensen ruimte of inkomen verliezen, terwijl anderen beter beschermd raken. Betrek hen bij het plan.',question:'Wat maakt een voorstel beter onderbouwd?',options:[['voices','Onderzoek natuurfunctie, inkomen en toegang, en maak samen afspraken over beheer en gevolgen.'],['profit','Alleen de opbrengst van de nieuwe kust bekijken.'],['nature','Mensen buitensluiten omdat natuur het enige belang is.']],correct:'voices',feedback:'Precies. Duurzame waarde verbindt ecologische, sociale en economische gevolgen. De plaatselijke bewoners leveren kennis over gebruik en risico; een financieel voordeel maakt hun verlies niet automatisch acceptabel.',ids:['stakeholder-perspectives','people-planet-prosperity'],source:'community',extra:'Dit is een fictieve situatie waarin je leert vragen wie gevolgen ervaart, wie invloed heeft en wie verantwoordelijk wordt voor onderhoud. Er is geen universeel juiste aanlegkeuze voor iedere kust.'}
};
export function fieldPanel(id,state){const s=stops[id];if(!s)return '<p>Onderzoek het landschap via een herkenningspunt.</p>';const done=state.flags['field-'+id]===true,src=sources[s.source];return `<section class="activity"><h2>${escape(s.title)}</h2><p>${escape(s.intro)}</p><details><summary>Leg het proces verder uit</summary><p>${escape(s.extra)}</p></details><h3>${escape(s.question)}</h3><div class="activity-actions">${s.options.map(([value,label])=>`<button data-act="fieldAnswer" data-field-id="${id}" data-value="${value}">${escape(label)}</button>`).join('')}</div>${done?'<p class="status-strip done">✓ Dit inzicht staat in je veldboek.</p>':''}<label class="mini-note">Mijn waarneming<textarea data-note="field-${id}" rows="2">${escape(state.notes['field-'+id]||'')}</textarea></label><p class="fine">Verbeeld landschap · <a href="${src[1]}" target="_blank" rel="noopener">${escape(src[0])}</a></p></section>`;}
export function fieldAction(id,value,state){const s=stops[id];if(!s)return {correct:false,message:'Kies een onderzoekspunt.'};if(value!==s.correct)return {correct:false,message:'Kijk welke oorzaak en welk gevolg de uitleg verbindt. Open de verdere uitleg en vergelijk de alternatieven.'};state.flags['field-'+id]=true;return {correct:true,message:s.feedback,conceptIds:s.ids};}
